import{_ as r,o as a,c as n,a2 as i}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"打包与部署：可执行 jar、容器与原生镜像","description":"","frontmatter":{"title":"打包与部署：可执行 jar、容器与原生镜像"},"headers":[{"level":2,"title":"本篇小节","slug":"本篇小节","link":"#本篇小节","children":[]}],"relativePath":"ch11/index.md","filePath":"ch11/index.md","lastUpdated":1789497795000}'),o={name:"ch11/index.md"};function t(l,e,c,s,g,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="打包与部署-可执行-jar、容器与原生镜像" tabindex="-1">打包与部署：可执行 jar、容器与原生镜像 <a class="header-anchor" href="#打包与部署-可执行-jar、容器与原生镜像" aria-label="Permalink to &quot;打包与部署：可执行 jar、容器与原生镜像&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">本篇对应官方章节</p><p><a href="https://docs.spring.io/spring-boot/reference/packaging/index.html" target="_blank" rel="noreferrer">打包总览</a> · <a href="https://docs.spring.io/spring-boot/reference/packaging/efficient.html" target="_blank" rel="noreferrer">高效打包</a> · <a href="https://docs.spring.io/spring-boot/reference/packaging/container-images/dockerfiles.html" target="_blank" rel="noreferrer">Dockerfile</a> · <a href="https://docs.spring.io/spring-boot/reference/packaging/container-images/cloud-native-buildpacks.html" target="_blank" rel="noreferrer">Buildpacks</a> · <a href="https://docs.spring.io/spring-boot/reference/packaging/aot.html" target="_blank" rel="noreferrer">AOT 处理</a> · <a href="https://docs.spring.io/spring-boot/reference/packaging/native-image/index.html" target="_blank" rel="noreferrer">GraalVM 原生镜像</a> · <a href="https://docs.spring.io/spring-boot/reference/using/packaging-for-production.html" target="_blank" rel="noreferrer">生产环境打包</a></p></div><p>上一篇把应用变得可观测了，但还有个更前面的问题没回答：<strong>它现在只能在你机器的 IDE 里跑。</strong></p><p>交付一个后端应用，要的不是“在我这儿能跑”，而是一个可以复制、可以分发、可以在别人机器上启动的东西。这一篇就从 <code>mvn package</code> 产出的那个 jar 开始，一路走到容器镜像和原生可执行文件。</p><p>具体回答五个问题：</p><ul><li><strong>那个 62MB 的 jar 里到底装了什么</strong>：为什么 <code>BOOT-INF</code>、<code>org/springframework/boot/loader</code> 这些目录不能删，<code>Main-Class</code> 为什么指向框架的类而不是你的主类</li><li><strong>分层是怎么工作的</strong>：<code>layers.idx</code> 把 jar 分成四层的依据是什么，4.x 的 <code>jarmode</code> 换成了什么，为什么解压之后启动更快</li><li><strong>容器化的两个细节</strong>：为什么分层镜像和单层镜像大小一样却不一样快，为什么 <code>chown</code> 写错位置会让镜像凭空多出 64MB</li><li><strong>JVM 上的 AOT 与 CDS</strong>：不编译原生镜像也能做的两项优化，实测能把启动从 4.8 秒压到 1.65 秒，以及它们各自的限制</li><li><strong>GraalVM 原生镜像</strong>：构建代价、运行时取舍，以及它和 Spring 的封闭世界假设冲突在哪里</li></ul><p>实测环境是本机 Java 21（Liberica）、Maven 3.9.11、Docker 29.4.0，另外单独装了 GraalVM 25.0.4 用于原生编译。所有启动耗时都是同一台机器上三次运行的结果，取中位数作参考。</p><hr><h2 id="本篇小节" tabindex="-1">本篇小节 <a class="header-anchor" href="#本篇小节" aria-label="Permalink to &quot;本篇小节&quot;">​</a></h2><ul><li><a href="/backend-engineering-course/ch11/01.html">11.1 可执行 jar 里装了什么</a></li><li><a href="/backend-engineering-course/ch11/02.html">11.2 jarmode 从 layertools 换成了 tools</a></li><li><a href="/backend-engineering-course/ch11/03.html">11.3 四层是按“变化频率”切的</a></li><li><a href="/backend-engineering-course/ch11/04.html">11.4 JVM 上的 AOT：把 Bean 定义在构建期算好</a></li><li><a href="/backend-engineering-course/ch11/05.html">11.5 CDS：把类加载的结果存下来</a></li><li><a href="/backend-engineering-course/ch11/06.html">11.6 容器化：两个容易被忽略的细节</a></li><li><a href="/backend-engineering-course/ch11/07.html">11.7 Buildpacks：不写 Dockerfile 的路线</a></li><li><a href="/backend-engineering-course/ch11/08.html">11.8 GraalVM 原生镜像</a></li><li><a href="/backend-engineering-course/ch11/09.html">11.9 从“能跑”到“能在生产上跑”</a></li><li><a href="/backend-engineering-course/ch11/10.html">11.10 问题速查</a></li><li><a href="/backend-engineering-course/ch11/11.html">11.11 小结与下一步</a></li></ul>',10)])])}const f=r(o,[["render",t]]);export{p as __pageData,f as default};
